import { expect, test } from "@playwright/test";

// One behavior per test, read as a reader driving the browser — see
// playwright.config.ts for the server these run against.

test("home page lists every post as a link to its detail page", async ({
	page,
}) => {
	await page.goto("/");

	const posts = page.getByRole("list", { name: "posts" }).getByRole("listitem");

	await expect(posts).not.toHaveCount(0);
	for (const post of await posts.all()) {
		await expect(post.getByRole("link")).toHaveAttribute("href", /^\/posts\//);
	}
});

test("visiting an unknown post slug renders the not-found page", async ({
	page,
}) => {
	const response = await page.goto("/posts/does-not-exist");

	expect(response?.status()).toBe(404);
});

import type { Post } from "@/shared/resolve-translation";

/**
 * The post catalog. It is checked in and compiled into the build. Reading it
 * from a content backend instead is a later change.
 */
export const POSTS: readonly Post[] = [
	{
		slug: "hello-world",
		defaultLocale: "ja-JP",
		translations: [
			{
				locale: "ja-JP",
				title: "はじめまして",
				body: "このブログについて書きました。",
			},
			{
				locale: "en-US",
				title: "Hello, world",
				body: "A short note about this blog.",
			},
		],
	},
	{
		slug: "on-writing-in-two-languages",
		defaultLocale: "ja-JP",
		translations: [
			{
				locale: "ja",
				title: "二言語で書くということ",
				body: "日本語と英語で書く理由について。",
			},
		],
	},
	{
		slug: "draft-notes",
		defaultLocale: "ja-JP",
		// A post that has not been translated into anything yet.
		translations: [],
	},
];

/** The post whose slug is `slug`, or `undefined` when the catalog has none. */
export function findPostBySlug(slug: string): Post | undefined {
	return POSTS.find((post) => post.slug === slug);
}

